{"modifiedFiles":[],"workingNote":"リポジトリ構成を確認し、既存の状態遷移・公開プロトコル・テストを特定します。"}{"modifiedFiles":[{"path":"src/protocol_adapter.ts","content":"export type WorldStateHandle = Readonly<Record<string, string>>;

export interface WorldProtocol {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(state: WorldStateHandle, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

const initialState: WorldStateHandle = {
  Zef: "pex",
};

function cloneState(state: WorldStateHandle): WorldStateHandle {
  return { ...state };
}

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return cloneState(initialState);
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldStateHandle }
    | { success: false; error: string } {
    const currentState = state.Zef;

    if (operationDisplayName === "advanceZef") {
      if (currentState !== "pex") {
        return {
          success: false,
          error: "advanceZef can only be applied when Zef is in pex",
        };
      }

      return {
        success: true,
        newState: { ...cloneState(state), Zef: "dor" },
      };
    }

    if (operationDisplayName === "recoverZef") {
      if (currentState !== "dor") {
        return {
          success: false,
          error: "recoverZef can only be applied when Zef is in dor",
        };
      }

      return {
        success: true,
        newState: { ...cloneState(state), Zef: "pex" },
      };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldStateHandle, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return { ...state };
  },
};
"}],"workingNote":"Zef の状態を pex→dor と進める既存操作に加え、dor の場合だけ recoverZef で pex に戻す遷移を追加しました。状態は各操作で複製し、公開プロトコルの4メソッドと戻り値形状を維持しています。"}

